def frames(g):
    h,w=len(g),len(g[0]); out=[]
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==0: continue
            if r>0 and g[r-1][c]==col: continue
            if c>0 and g[r][c-1]==col: continue
            for hh in range(2,h-r+1):
                for ww in range(2,w-c+1):
                    border_ok=all(g[r][c+k]==col and g[r+hh-1][c+k]==col for k in range(ww)) and \
                              all(g[r+k][c]==col and g[r+k][c+ww-1]==col for k in range(hh))
                    if not all(g[r][c+k]==col for k in range(ww)): break
                    if not border_ok: continue
                    inner={g[i][j] for i in range(r+1,r+hh-1) for j in range(c+1,c+ww-1)}
                    if len(inner)==1 and col not in inner:
                        out.append((r,c,hh,ww,col,inner.pop()))
                if not all(g[r][c+k]==col for k in range(2)): break
    return out

def transform(g):
    g=[row[:] for row in g]
    hs,ws=len(g),len(g[0])
    for (r,c,hh,ww,col,ic) in frames(g):
        area=(hh-2)*(ww-2)
        f=7 if area%2==1 else 2
        for i in range(r+1,r+hh-1):
            for j in range(c+1,c+ww-1):
                g[i][j]=f
    return g

